import React, { Fragment, useState } from "react";
import { Tabs, Badge, TabsProps } from "@arco-design/web-react";
import { ArrayField } from "@formily/core";
import {
  useField,
  observer,
  useFieldSchema,
  RecursionField,
  ReactFC,
  VoidField,
} from "@formily/react";
import toArray from "rc-util/es/Children/toArray";
import ArrayBase from "../ArrayBase";

interface IFeedbackBadgeProps {
  index: number;
}

const FeedbackBadge: ReactFC<IFeedbackBadgeProps> = observer(
  (props) => {
    const field = useField<ArrayField>();
    const tab = `${field.title || "Untitled"} ${props.index + 1}`;
    const errors = field.errors.filter((error) =>
      error?.address?.includes(`${field.address}.${props.index}`)
    );
    if (errors.length) {
      return (
        <Badge className="errors-badge" count={errors.length}>
          {tab}
        </Badge>
      );
    }
    return <Fragment>{tab}</Fragment>;
  },
  {
    scheduler(request) {
      requestAnimationFrame(request);
    },
  }
);

export const ArrayTabs: React.FC<
  React.PropsWithChildren<TabsProps & { mode?: "jsx" | "schema" }>
> = (props) => {
  const { mode, ...rest } = props;
  if (mode === "jsx") {
    return <ArrayJSXTabs {...rest} />;
  } else {
    return <ArraySchemaTabs {...rest} />;
  }
};

export const ArraySchemaTabs: React.FC<
  React.PropsWithChildren<TabsProps>
> = observer(
  (props) => {
    const field = useField<ArrayField>();
    const schema = useFieldSchema();
    const [activeKey, setActiveKey] = useState("tab-0");
    const value = Array.isArray(field.value) ? field.value : [];
    const dataSource = value?.length ? value : [{}];
    const onEdit = (targetKey: any, type: "add" | "remove") => {
      if (type == "add") {
        const id = dataSource.length;
        if (field?.value?.length) {
          field.push(null);
        } else {
          field.push(null, null);
        }
        setActiveKey(`tab-${id}`);
      } else if (type == "remove") {
        const index = Number(targetKey.match(/-(\d+)/)?.[1]);
        if (index - 1 > -1) {
          setActiveKey(`tab-${index - 1}`);
        }
        field.remove(index);
      }
    };
    return (
      <Tabs
        editable
        {...props}
        activeTab={activeKey}
        onChange={(key) => {
          setActiveKey(key);
        }}
        type="card-gutter"
        onAddTab={() => onEdit("", "add")}
        onDeleteTab={(key) => onEdit(key, "remove")}
      // renderTabHeader={(tabProps, DefaultTabHeader) => {
      //   return (
      //     <div>
      //       <DefaultTabHeader {...tabProps} />
      //     </div>
      //   );
      // }}
      // renderTabTitle={(tabTitle, info) => {
      //   // return tabTitle;
      //   return (
      //     <div
      //       key={info.key}
      //       onClick={() => setActiveKey(info.key)}
      //       style={{ marginRight: 50, display: "inline-flex" }}
      //     >
      //       XXXXXXX
      //     </div>
      //   );
      // }}
      >
        {dataSource?.map((item, index) => {
          const items = Array.isArray(schema.items)
            ? schema.items[index]
            : schema.items;
          const key = `tab-${index}`;
          return (
            <Tabs.TabPane
              key={key}
              destroyOnHide={false}
              closable={index !== 0}
              title={<FeedbackBadge index={index} />}
            >
              <RecursionField schema={items!} name={index} />
            </Tabs.TabPane>
          );
        })}
      </Tabs>
    );
  },
  {
    scheduler(request) {
      requestAnimationFrame(request);
    },
  }
);

const ArrayJSXTabs: React.FC<React.PropsWithChildren<TabsProps>> = observer(
  (props) => {
    const field = useField<ArrayField>();
    const childNodes = toArray(props.children, { keepEmpty: false });
    const [item] = childNodes;

    const [activeKey, setActiveKey] = useState("tab-0");
    const value = Array.isArray(field.value) ? field.value : [];
    const dataSource = value?.length ? value : [{}];
    const onEdit = (targetKey: any, type: "add" | "remove") => {
      if (type == "add") {
        const id = dataSource.length;
        if (field?.value?.length) {
          field.push(null);
        } else {
          field.push(null, null);
        }
        setActiveKey(`tab-${id}`);
      } else if (type == "remove") {
        const index = Number(targetKey.match(/-(\d+)/)?.[1]);
        if (index - 1 > -1) {
          setActiveKey(`tab-${index - 1}`);
        }
        field.remove(index);
      }
    };
    return (
      <ArrayBase mode="jsx">
        <Tabs
          editable
          {...props}
          activeTab={activeKey}
          onChange={(key) => {
            setActiveKey(key);
          }}
          type="card-gutter"
          onAddTab={() => onEdit("", "add")}
          onDeleteTab={(key) => onEdit(key, "remove")}
        >
          {dataSource?.map((_, index) => {
            const key = `tab-${index}`;
            return (
              <Tabs.TabPane
                key={key}
                destroyOnHide={false}
                closable={index !== 0}
                title={<FeedbackBadge index={index} />}
              >
                <ArrayBase.Item
                  key={index}
                  index={index}
                  record={() => field.value?.[index]}
                >
                  <VoidField name={index}>{item}</VoidField>
                </ArrayBase.Item>
              </Tabs.TabPane>
            );
          })}
        </Tabs>
      </ArrayBase>
    );
  },
  {
    scheduler(request) {
      requestAnimationFrame(request);
    },
  }
);

export default ArrayTabs;
